@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
  + hasOscar : boolean
}

class CreativeEmployee extends Employee {
}

class Director extends CreativeEmployee {
  + assistantName : string
}

class Actor extends CreativeEmployee {
  + education : string
}

class Technician extends Employee {
  + fieldOfActivity : string
}

class Location {
  + name : string
}

class Film {
  + title : string
  + releaseYear : int
}

class Genre {
}

class Thriller extends Genre {}
class Action extends Genre {}
class Horror extends Genre {}
class Comedy extends Genre {}

class Screenwriter {
  + name : string
  + mostSuccessfulFilm : string
}

class Screenplay {
  + title : string
  + version : string
  + date : date
  + numberOfScenes : int
  + plot : string
}

class Novel {
  + title : string
}

class Author {
  + name : string
}

class Concept {
}

Film "*" -- "*" Location : used at
Film "1" -- "1" Genre : assigned to
Film "1" -- "1" Screenplay : based on
Screenplay "1" -- "1" Screenwriter : written by
Screenplay "1" -- "0..1" Novel : based on
Screenplay "1" -- "0..1" Concept : based on
Actor "1..*" -- "1" Screenplay : prepares for role in
Director "1" -- "1" Screenplay : implements

Screenwriter "1" -- "*" Screenplay : creates
Novel "1" -- "1" Author : written by
Actor "1..*" -- "1" Film : appears in

@enduml

